/**
 * Determines whether an automatic row limit should be appended to a SQL query.
 *
 * An auto limit is only appended when the query is a "simple" single SELECT
 * statement that doesn't already constrain the number of rows returned.
 */
export const checkIfAppendLimitRequired = (sql: string, limit: number = 0) => {
  const cleanedSql = sql.trim()

  // A single statement produces at most one non-empty segment when split on `;`.
  const hasMultipleStatements =
    cleanedSql.split(';').filter((statement) => statement.trim().length > 0).length > 1

  const appendAutoLimit =
    limit > 0 &&
    !cleanedSql.includes('--') &&
    !hasMultipleStatements &&
    /^select/i.test(cleanedSql) &&
    !/\blimit\b/i.test(cleanedSql)

  return { appendAutoLimit }
}

/**
 * Appends ` limit {limit};` to a SQL query, ensuring the result ends with
 * exactly one semicolon regardless of how many trailing semicolons the
 * original query had.
 */
export const suffixWithLimit = (sql: string, limit: number = 0) => {
  const cleanedSql = sql.trim().replace(/[\s;]+$/, '')
  return `${cleanedSql} limit ${limit};`
